// CarPlay map-button glyphs — OUR artwork, not SF Symbols.
//
// WHY DATA URIs (and why this is OTA-able on an existing binary):
// CPMapButton only takes a UIImage, and react-native-carplay builds it with
// [RCTConvert UIImage:] (RCTConvert+RNCarPlay.m). Our own code comments used to
// claim custom images simply cannot work under bridgeless — that is WRONG, and
// it cost us the SF-Symbol detour. RCTConvert.mm:1339 has a dedicated `data:`
// branch that decodes inline via [UIImage imageWithData:] with NO bridge and NO
// image loader, and resolveAssetSource.js:112 returns {uri} objects untouched,
// so a data URI survives our patched parseConfig/traverse verbatim. The whole
// chain is JS + stock RN native code that already ships in build 67 — no native
// patch, no new build.
//
// It also dodges the OTA asset path-key trap (see the ota-asset-path-key-trap
// note): expo-updates dedupes embedded assets by PATH, so editing a require()'d
// PNG's CONTENT via OTA silently serves the OLD embedded copy. These bytes live
// in the JS bundle itself, so changing a glyph always takes effect.
//
// SIZING: RCTImageSource.m:73 reads `scale` off the dict, so 132px art at
// scale 3 lands as a crisp 44pt button glyph.
//
// TO SHRINK A GLYPH, PAD IT — DO NOT TOUCH `scale`. CPMapButton/CPBarButton draw
// the image inside a fixed system circle, so the lever that actually changes how
// big the ink looks is how much of the 132px canvas the ink covers. Shrinking via
// `scale` would change the image's POINT box (44pt) and move the button layout
// with it; transparent padding leaves the box alone and only makes the drawing
// smaller. The mic and crew glyphs below are drawn at 0.74 of the canvas for that
// reason (Jeff, 2026-07-25: "shrink the glyph for the comms mic and crew").
// Regenerate with the pad/tint + compass helper kept in the OTA commit message,
// or redraw at CANVAS*frac centred and re-base64.
//
// focusedImage IS SUPPLIED DELIBERATELY: CarPlay flattens the focused state to a
// solid system-focus-colour silhouette when focusedImage is nil (CPMapButton.h:51-52
// documents the alpha-derived behaviour). Passing our own art keeps the real
// glyph while a rotary-controller head unit has it focused.
//
// Source art: assets/images/police.png + assets/images/scout-mic.png — the SAME
// files the phone HUD uses (src/components/MapControlIcons.tsx, and the Scout mic
// button below), which is the standing "CarPlay matches the phone" rule.
// Regenerate: sips -Z 132 <src>.png, then base64.

type CarIcon = { uri: string; width: number; height: number; scale: number };

const icon = (b64: string): CarIcon => ({
  uri: 'data:image/png;base64,' + b64,
  width: 44,
  height: 44,
  scale: 3,
});

export const CAR_ICON_POLICE: CarIcon = icon(
  '',
);

export const CAR_ICON_MIC: CarIcon = icon(
  '',
);

// A fully TRANSPARENT glyph, used only as a layout spacer. CarPlay BOTTOM-anchors
// the map-button column, so the only way to lift the real buttons out of the
// bottom-right (where our maneuver banner lives) is to occupy the lower slots.
// `hidden: true` does NOT work — verified in the sim, the buttons still drew — so
// the spacer is an invisible, DISABLED button instead.
export const CAR_ICON_BLANK: CarIcon = icon(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==',
);

// ── Saved-place glyphs for the CarPlay SEARCH list ───────────────────────────
// The SAME Ionicons the phone's search screen draws (NavSearchScreen.tsx: "home" /
// "briefcase" / "bookmark"), rasterised from the very same Ionicons.ttf that ships in
// @expo/vector-icons via CoreText, so the two surfaces cannot drift — that is the
// standing "CarPlay matches the phone" rule.
// CPListItem takes a UIImage through the same [RCTConvert UIImage:] data-URI path as the
// map buttons (parseListItems in RCTConvert+RNCarPlay.m), so these are OTA-able too.
// Regenerate: swift glyph.swift <Ionicons.ttf> <hex codepoint> 132 out.png, then base64.
//   home f382 · briefcase f1b1 · bookmark f1a8

export const CAR_ICON_HOME: CarIcon = icon(
  '',
);

export const CAR_ICON_WORK: CarIcon = icon(
  '',
);

export const CAR_ICON_SAVED: CarIcon = icon(
  '',
);

// Crew + compass glyphs for the CarPlay map buttons.
//
// CREW: the Ionicons "people" silhouette (same glyph as the phone's Crew FAB),
// tinted BRAND GREEN #2DEC86 and drawn at 0.74 of the canvas. The phone FAB was
// changed to the same green in the same pass, so the two surfaces match.
//
// COMPASS: NOT an Ionicons compass any more. This is the phone's own needle —
// the exact polygons from src/components/CompassNeedle.tsx (100-unit viewBox,
// green north arm / white south arm / #3A3A3C shadow facets / white pin with a
// #1C1C1E ring), rasterised at 0.92 of the canvas. Previously CarPlay drew a
// generic filled-circle compass while the phone drew the faceted needle, which
// is exactly the drift the "CarPlay matches the phone" rule exists to prevent.
//
// KNOWN, AND FAITHFUL: the #3A3A3C shadow facets nearly vanish against CarPlay's
// always-dark button, so the needle reads as half a spindle there. The phone does
// the SAME thing over a dusk/night basemap — it only looks two-toned over a light
// map. Lifting the shadow colour would make the head unit read better but would
// no longer be an exact copy, so it is deliberately left alone.
export const CAR_ICON_CREW: CarIcon = icon(
  '',
);

export const CAR_ICON_COMPASS: CarIcon = icon(
  '',
);
